import{_ as e,o,c as a,ag as i}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"区域（Regions）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Other/Regions.md","filePath":"zh/Other/Regions.md"}'),r={name:"zh/Other/Regions.md"};function n(s,t,u,l,m,q){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="区域-regions" tabindex="-1">区域（Regions） <a class="header-anchor" href="#区域-regions" aria-label="Permalink to &quot;区域（Regions）&quot;">​</a></h1><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><p>在生成随机地图时（仅限随机地图；不包括预置地图），地图会被划分为与主要文明数量相等的多个区域。每个区域根据其主流地形分类，无法分类的称为&quot;混合&quot;（hybrid）区域。 区域类型与文明分配时的起始偏好（start bias）相对应。 区域类型还决定起始位置以及该区域会出现哪些奢侈品。</p><details><summary>示例</summary><img src="https://user-images.githubusercontent.com/63475501/140308518-ad5a2f50-d5f1-4467-a296-3a67f6d0b007.png" alt="区域示例"></details><h2 id="如何在模组中定义区域行为" tabindex="-1">如何在模组中定义区域行为 <a class="header-anchor" href="#如何在模组中定义区域行为" aria-label="Permalink to &quot;如何在模组中定义区域行为&quot;">​</a></h2><p>游戏在没有额外 json 定义的情况下也能工作，但如果你希望区域系统在为你的模组生成地图时良好运作，就需要定义这些相关的 unique。</p><h3 id="terrains-json" tabindex="-1">Terrains.json <a class="header-anchor" href="#terrains-json" aria-label="Permalink to &quot;Terrains.json&quot;">​</a></h3><p>&quot;Always Fertility [amount] for Map Generation&quot;（地图生成时始终为 [amount] 肥沃度）、&quot;[amount] to Fertility for Map Generation&quot;（地图生成时肥沃度 +[amount]）——决定一种地形在公平划分土地方面的优劣。数值是任意的，但应反映各地形的相对价值。</p><p>&quot;A Region is formed with at least [amount]% [simpleTerrain] tiles, with priority [amount]&quot;（至少含 [amount]% [simpleTerrain] 地块的区域形成，优先级 [amount]）、 &quot;A Region is formed with at least [amount]% [simpleTerrain] tiles and [simpleTerrain] tiles, with priority [amount]&quot;（至少含 [amount]% [simpleTerrain] 地块和 [simpleTerrain] 地块的区域形成，优先级 [amount]）——决定一个区域何时被归类为例如&quot;沙漠&quot;区域的规则。地形按优先级升序评估，所以基础规则集中冻土地带优先被检查。 &quot;A Region can not contain more [simpleTerrain] tiles than [simpleTerrain] tiles&quot;（区域中的 [simpleTerrain] 地块不能多于 [simpleTerrain] 地块）——对上面&quot;双地形之和&quot;标准的实用补充，适用于两种地形本身都是地形类型的情况。所以基础规则集中，丛林与森林之和足够大时区域可被归类为丛林，但前提是丛林要多于森林。 &quot;Base Terrain on this tile is not counted for Region determination&quot;（此地块的基础地形不计入区域判定）——用于不可移除或以其他方式主导地块的地形特征。基础规则集中用于丘陵。 不满足任何标准的区域被归类为&quot;混合&quot;。</p><p>&quot;Considered [terrainQuality] when determining start locations&quot;（确定起始位置时视为 [terrainQuality]）——其中 &quot;terrainQuality&quot; 是 &quot;Food&quot;（食物）、&quot;Production&quot;（产能）、&quot;Desirable&quot;（理想）、&quot;Undesirable&quot;（不理想）之一。通常与 &quot;<code>&lt;in [regionType] Regions&gt;</code>&quot;（位于 [regionType] 区域）或 &quot;<code>&lt;in all except [regionType] Regions&gt;</code>&quot;（位于除 [regionType] 外的所有区域）配合使用，决定确定起始位置时什么地形有吸引力。注意：如果某地形没有这些定义，游戏会用该地形的基础数值来推断质量；但只要有任何定义，游戏就会假定它们是完整的。</p>',10)])])}const h=e(r,[["render",n]]);export{p as __pageData,h as default};
